1	import {
2	  openSync,
3	  closeSync,
4	  writeSync,
5	  fsyncSync,
6	  mkdirSync,
7	  readFileSync,
8	  writeFileSync,
9	  truncateSync,
10	  renameSync,
11	  rmSync,
12	  existsSync,
13	  readdirSync,
14	  statSync,
15	} from 'node:fs';
16	import path from 'node:path';
17	import { randomUUID } from 'node:crypto';
18	
19	const LOG_NAME = 'bus.jsonl';
20	const LOG_TMP_NAME = 'bus.log.tmp';
21	const SNAPSHOT_NAME = 'bus.snapshot.json';
22	const SNAPSHOT_TMP_NAME = 'bus.snapshot.tmp';
23	// The log is a chain of segment files: the active `bus.jsonl` plus finalized
24	// `bus.<index>.jsonl` segments. Index order is oldest first; an index is
25	// never reused within the lifetime of a directory.
26	const SEGMENT_RE = /^bus\.(\d+)\.jsonl$/;
27	const segmentName = (index) => `bus.${String(index).padStart(10, '0')}.jsonl`;
28	
29	/**
30	 * Validate that `value` survives a compact JSON.stringify unchanged.
31	 * JSON silently drops undefined / functions and turns non-finite numbers
32	 * into null; the spec rejects those along with BigInt and circular
33	 * references as TypeError.
34	 */
35	function assertJsonSafe(value, stack = new Set()) {
36	  if (typeof value === 'bigint') {
37	    throw new TypeError('record contains a BigInt');
38	  }
39	  if (typeof value === 'function') {
40	    throw new TypeError('record contains a function');
41	  }
42	  if (typeof value === 'undefined') {
43	    throw new TypeError('record contains undefined');
44	  }
45	  if (typeof value === 'number' && !Number.isFinite(value)) {
46	    throw new TypeError('record contains a non-finite number');
47	  }
48	  if (value !== null && typeof value === 'object') {
49	    // Unbox boxed primitives (e.g. new Number(NaN)) before recursing.
50	    if (value instanceof Number || value instanceof String || value instanceof Boolean) {
51	      assertJsonSafe(value.valueOf(), stack);
52	      return;
53	    }
54	    if (stack.has(value)) {
55	      throw new TypeError('record contains a circular reference');
56	    }
57	    stack.add(value);
58	    if (Array.isArray(value)) {
59	      for (const item of value) assertJsonSafe(item, stack);
60	    } else {
61	      for (const key of Object.keys(value)) assertJsonSafe(value[key], stack);
62	    }
63	    stack.delete(value);
64	  }
65	}
