67	/**
68	 * Split a jsonl buffer into parsed entries. `durable` is the offset just
69	 * past the final newline; anything beyond it is a torn trailing write.
70	 */
71	function parseLog(raw) {
72	  const entries = [];
73	  let start = 0;
74	  for (let i = 0; i < raw.length; i++) {
75	    if (raw[i] === 0x0a) {
76	      if (i > start) entries.push(JSON.parse(raw.toString('utf8', start, i)));
77	      start = i + 1;
78	    }
79	  }
80	  return { entries, durable: start };
81	}
