83	export function createBus({ path: dir, fsync = false } = {}) {
84	  if (typeof dir !== 'string' || dir.length === 0) {
85	    throw new TypeError('createBus: "path" must be a non-empty string');
86	  }
87	
88	  const logPath = path.join(dir, LOG_NAME);
89	  const logTmpPath = path.join(dir, LOG_TMP_NAME);
90	  const snapshotPath = path.join(dir, SNAPSHOT_NAME);
91	  const snapshotTmpPath = path.join(dir, SNAPSHOT_TMP_NAME);
92	
93	  let seq = 0; // seq of the last effective message
94	  let bytes = 0;
95	  let published = 0;
96	  let replayed = 0;
97	  // dedupKey -> { id, seq } for effective messages
98	  const dedup = new Map();
99	  // dedupKey -> { promise, resolve, reject } for first publish in flight
100	  const pending = new Map();
101	  // dedupKey -> { promise, resolve, reject } reserved by the first
102	  // in-flight batch carrying that key; lets later singles/batches share
103	  // the batch's first acknowledgement just like `pending` does for singles
104	  const groupPending = new Map();
105	  // consumer name -> position (seq of the last consumed message; 0 = none)
106	  const positions = new Map();
107	  // generation of the newest durable snapshot; 0 = no snapshot yet
108	  let snapshotGen = 0;
109	  // messages folded into the snapshot, served to replay/read after truncation
110	  let baseMessages = [];
111	  // Every message with seq <= horizon has been discarded by truncate().
112	  let horizon = 0;
113	  // Every message with seq <= foldedSeq lives in the snapshot, not the log.
114	  let foldedSeq = 0;
115	  // Index handed to the next finalized segment; never reused within a run.
116	  let nextSegmentIndex = 1;
117	
118	  // ---- synchronous recovery so stats() is correct the moment createBus returns
119	  mkdirSync(dir, { recursive: true });
120	
121	  // A leftover tmp file is a snapshot that crashed mid-write. The pre-compact
122	  // log is still intact, so the half snapshot carries no state: drop it.
123	  rmSync(snapshotTmpPath, { force: true });
124	  // Likewise a log tmp left behind when compact crashed before the rename:
125	  // the live log (if any) is still the source of truth.
126	  rmSync(logTmpPath, { force: true });
127	
128	  if (existsSync(snapshotPath)) {
129	    const snap = JSON.parse(readFileSync(snapshotPath, 'utf8'));
130	    snapshotGen = snap.gen;
131	    seq = snap.seq;
132	    bytes = snap.bytes;
133	    published = snap.published;
134	    replayed = snap.replayed;
135	    // Snapshots written before truncation existed carry no horizon.
136	    horizon = snap.horizon ?? 0;
137	    foldedSeq = snap.seq;
138	    for (const [key, value] of snap.dedup) dedup.set(key, value);
139	    for (const [name, pos] of Object.entries(snap.positions)) positions.set(name, pos);
140	    baseMessages = snap.messages;
141	  }
142	
143	  const applyEntry = (entry) => {
144	    if (entry.t === 'm') {
145	      // At/below the horizon the message was discarded by truncation; only
146	      // its cumulative counters (carried by the marker) survive.
147	      if (entry.seq <= horizon) return;
148	      seq = entry.seq;
149	      bytes += entry.bytes;
150	      published += 1;
151	      if (typeof entry.d === 'string') {
152	        dedup.set(entry.d, { id: entry.id, seq: entry.seq });
153	      }
154	    } else if (entry.t === 's') {
155	      replayed += entry.n;
156	    } else if (entry.t === 'p') {
157	      positions.set(entry.name, entry.pos);
158	    }
159	  };
160	
161	  // A truncate marker is an absolute checkpoint: the cumulative counters,
162	  // positions and dedup table it carries replace whatever earlier segments
163	  // established, so recovery can start from the newest marker and ignore
164	  // everything before it.
165	  const applyMarker = (entry) => {
166	    seq = entry.seq;
167	    bytes = entry.bytes;
168	    published = entry.published;
169	    replayed = entry.replayed;
170	    horizon = entry.horizon;
171	    positions.clear();
172	    for (const [name, pos] of Object.entries(entry.positions)) positions.set(name, pos);
173	    dedup.clear();
174	    for (const [key, value] of entry.dedup) dedup.set(key, value);
175	  };
176	
177	  const markerLine = (gen) => JSON.stringify({ t: 'c', gen }) + '\n';
178	
179	  // Replay complete log lines and apply only the committed prefix.
180	  // A batch is bracketed by {t:'b',id} .. entries .. {t:'bk',id}: a begin
181	  // without its matching commit (crash mid-write, or overtaken by a newer
182	  // begin) is severed wholesale and none of its entries take effect.
183	  // Returns the byte offset just past the last committed line, so both a
184	  // torn trailing write and an uncommitted batch tail can be truncated.
185	  const recoverLog = (raw) => {
186	    let lineStart = 0;
187	    let committedEnd = 0;
188	    let group = null;
189	    for (let i = 0; i < raw.length; i++) {
190	      if (raw[i] !== 0x0a) continue;
191	      const entry = i > lineStart ? JSON.parse(raw.toString('utf8', lineStart, i)) : null;
192	      if (group !== null) {
193	        if (entry && entry.t === 'bk' && entry.id === group.id) {
194	          for (const e of group.entries) applyEntry(e);
195	          group = null;
196	          committedEnd = i + 1;
197	        } else if (entry && entry.t === 'b') {
198	          // The previous group never committed; start tracking the new one.
199	          group = { id: entry.id, entries: [] };
200	        } else if (entry) {
201	          group.entries.push(entry);
202	        }
203	      } else if (entry && entry.t === 'b') {
204	        group = { id: entry.id, entries: [] };
205	      } else {
206	        if (entry) {
207	          if (entry.t === 't') applyMarker(entry);
208	          else applyEntry(entry);
209	        }
210	        committedEnd = i + 1;
211	      }
212	      lineStart = i + 1;
213	    }
214	    return committedEnd;
215	  };
216	
217	  // Finalized segments present in the directory, oldest first.
218	  const listSegments = () => {
219	    const out = [];
220	    for (const name of readdirSync(dir)) {
221	      const match = SEGMENT_RE.exec(name);
222	      if (match) out.push({ index: Number(match[1]), path: path.join(dir, name) });
223	    }
224	    out.sort((a, b) => a.index - b.index);
225	    return out;
226	  };
227	
228	  // First complete line of a log file, or null when there is none.
229	  const firstEntry = (filePath) => {
230	    const raw = readFileSync(filePath);
231	    const nl = raw.indexOf(0x0a);
232	    if (nl <= 0) return null;
233	    try {
234	      return JSON.parse(raw.toString('utf8', 0, nl));
235	    } catch {
236	      return null;
237	    }
238	  };
239	
240	  // Highest message seq in a segment file; null when it carries no messages.
241	  const segmentMaxSeq = (filePath) => {
242	    const { entries } = parseLog(readFileSync(filePath));
243	    let max = null;
244	    for (const entry of entries) {
245	      if (entry.t === 'm' && (max === null || entry.seq > max)) max = entry.seq;
246	    }
247	    return max;
248	  };
249	
250	  const segments = listSegments();
251	  for (const seg of segments) {
252	    if (seg.index >= nextSegmentIndex) nextSegmentIndex = seg.index + 1;
253	  }
254	  // The ordered log is every finalized segment (oldest first) followed by
255	  // the active log file.
256	  const ordered = segments.map((seg) => seg.path);
257	  if (existsSync(logPath)) ordered.push(logPath);
258	
259	  // The newest anchor — a segment whose first line is a compact ('c') or
260	  // truncate ('t') marker for the current snapshot generation — starts the
261	  // live suffix of the log. Everything before it is folded into the snapshot
262	  // or checkpointed into that marker.
263	  let startAt = -1;
264	  for (let i = 0; i < ordered.length; i++) {
265	    const first = firstEntry(ordered[i]);
266	    if (first && (first.t === 'c' || first.t === 't') && first.gen === snapshotGen) {
267	      startAt = i;
268	    }
269	  }
270	
271	  if (snapshotGen > 0 && startAt < 0) {
272	    // Crash between the snapshot rename and the log reset: every byte still
273	    // on disk is already folded into the snapshot. Reset to a marker-led log
274	    // so the state is unambiguous from here on.
275	    for (const seg of segments) rmSync(seg.path, { force: true });
276	    writeFileSync(logPath, markerLine(snapshotGen));
277	  } else {
278	    // Replay the live suffix; a torn tail or uncommitted batch is severed.
279	    for (let i = Math.max(startAt, 0); i < ordered.length; i++) {
280	      const raw = readFileSync(ordered[i]);
281	      const committedEnd = recoverLog(raw);
282	      if (committedEnd < raw.length) truncateSync(ordered[i], committedEnd);
283	    }
284	    // Reconcile leftovers of an interrupted truncate/compact: finalized
285	    // segments before the anchor whose content is folded into the snapshot
286	    // or at/below the truncation horizon can go. Segments a consumer still
287	    // needs (above the horizon) stay untouched.
288	    for (let i = 0; i < startAt; i++) {
289	      const max = segmentMaxSeq(ordered[i]);
290	      if (max === null || max <= foldedSeq || max <= horizon) {
291	        rmSync(ordered[i], { force: true });
292	      }
293	    }
294	  }
295	
296	  // Reassigned by compact()/truncate() when they swap the active log.
297	  let fd = openSync(logPath, 'a');
298	
299	  let chain = Promise.resolve();
300	  let closed = false;
301	  // A failed append may leave a torn line; stop appending so later writes
302	  // cannot glue themselves onto it. The torn tail is truncated on reopen.
303	  let broken = false;
304	
305	  // All disk mutation by publish/replay/compact/truncate happens inside this
306	  // serial chain; writeSync keeps each append atomic with respect to the
307	  // event loop while still returning a Promise to callers.
308	  const enqueue = (job) => {
309	    const run = chain.then(job);
310	    // A failed job must not stall every later operation.
311	    chain = run.then(
312	      () => {},
313	      () => {},
314	    );
315	    return run;
316	  };
317	
318	  const writeLine = (entry) => {
319	    writeSync(fd, Buffer.from(JSON.stringify(entry) + '\n', 'utf8'));
320	    if (fsync) fsyncSync(fd);
321	  };
322	
323	  // Position writes are synchronous (register/advance/read are synchronous
324	  // methods) and order-independent against 'm'/'s' entries, so they append
325	  // directly rather than through the chain.
326	  const persistPosition = (name, pos) => {
327	    try {
328	      writeLine({ t: 'p', name, pos });
329	    } catch (err) {
330	      broken = true;
331	      throw err;
332	    }
333	  };
334	
335	  const assertOpen = () => {
336	    if (closed || broken) {
337	      throw new Error('bus is closed');
338	    }
339	  };
340	
341	  const assertName = (name) => {
342	    if (typeof name !== 'string' || name.length === 0) {
343	      throw new TypeError('consumer name must be a non-empty string');
344	    }
345	  };
346	
347	  // Messages with seq > pos that survived truncation, snapshot first then
348	  // live segments, ascending. A position below the truncation horizon simply
349	  // starts at the earliest surviving message: the gap is already truncated.
350	  const messagesAfter = (pos) => {
351	    const floor = Math.max(pos, horizon);
352	    const out = [];
353	    for (const m of baseMessages) {
354	      if (m.seq > floor) {
355	        // Snapshot messages are shared in-memory objects; hand out a copy so
356	        // callers cannot mutate replay/read results for later calls.
357	        out.push({ seq: m.seq, id: m.id, record: structuredClone(m.record) });
358	      }
359	    }
360	    // Log entries at/below foldedSeq are covered by the snapshot (a leftover
361	    // segment from an interrupted compaction can still be on disk).
362	    const logFloor = Math.max(floor, foldedSeq);
363	    const collect = (filePath) => {
364	      const { entries } = parseLog(readFileSync(filePath));
365	      for (const entry of entries) {
366	        if (entry.t === 'm' && entry.seq > logFloor) {
367	          out.push({ seq: entry.seq, id: entry.id, record: entry.record });
368	        }
369	      }
370	    };
371	    for (const seg of listSegments()) collect(seg.path);
372	    collect(logPath);
373	    return out;
374	  };
375	
376	  const bus = {
377	    publish(record) {
378	      if (closed) {
379	        return Promise.reject(new Error('bus is closed'));
380	      }
381	      if (record === null || typeof record !== 'object' || Array.isArray(record)) {
382	        return Promise.reject(new TypeError('publish: record must be a JSON object'));
383	      }
384	      const dedupKey = record.dedupKey;
385	      if (dedupKey !== undefined && typeof dedupKey !== 'string') {
386	        return Promise.reject(new TypeError('publish: dedupKey must be a string'));
387	      }
388	      try {
389	        assertJsonSafe(record);
390	      } catch (err) {
391	        return Promise.reject(err);
392	      }
393	      const size = Buffer.byteLength(JSON.stringify(record), 'utf8');
394	
395	      // Duplicate of an effective message (possibly recovered from disk).
396	      if (dedupKey !== undefined) {
397	        const first = dedup.get(dedupKey);
398	        if (first) {
399	          return Promise.resolve({ id: first.id, seq: first.seq });
400	        }
401	        const inflight = pending.get(dedupKey);
402	        if (inflight) {
403	          return inflight.promise;
404	        }
405	        const inflightGroup = groupPending.get(dedupKey);
406	        if (inflightGroup) {
407	          return inflightGroup.promise;
408	        }
409	      }
410	
411	      // Reserve in-flight dedup at call time so concurrent resends of the
412	      // same order share the first result; FIFO enqueue assigns seq in
413	      // invocation order.
414	      let resolveResult;
415	      let rejectResult;
416	      const promise = new Promise((resolve, reject) => {
417	        resolveResult = resolve;
418	        rejectResult = reject;
419	      });
420	      if (dedupKey !== undefined) {
421	        pending.set(dedupKey, { promise, resolve: resolveResult, reject: rejectResult });
422	      }
423	
424	      enqueue(() => {
425	        if (closed || broken) {
426	          throw new Error('bus is closed');
427	        }
428	        const mySeq = seq + 1;
429	        const id = randomUUID();
430	        const entry = { t: 'm', seq: mySeq, id, bytes: size, record };
431	        if (dedupKey !== undefined) entry.d = dedupKey;
432	        try {
433	          // Durable before acknowledgement: state changes only after the
434	          // write (and optional fsync) succeeds.
435	          writeLine(entry);
436	        } catch (err) {
437	          broken = true;
438	          throw err;
439	        }
440	        seq = mySeq;
441	        bytes += size;
442	        published += 1;
443	        if (dedupKey !== undefined) {
444	          dedup.set(dedupKey, { id, seq: mySeq });
445	          pending.delete(dedupKey);
446	          resolveResult({ id, seq: mySeq });
447	        }
448	        return { id, seq: mySeq };
449	      }).then(
450	        (ack) => {
451	          if (dedupKey === undefined) resolveResult(ack);
452	        },
453	        (err) => {
454	          if (dedupKey !== undefined) pending.delete(dedupKey);
455	          rejectResult(err);
456	        },
457	      );
458	
459	      return promise;
460	    },
461	
462	    publishBatch(records) {
463	      // Spec: a non-array argument is always a synchronous TypeError.
464	      if (!Array.isArray(records)) {
465	        throw new TypeError('publishBatch: records must be an array');
466	      }
467	      if (closed) {
468	        return Promise.reject(new Error('bus is closed'));
469	      }
470	
471	      // Validate and serialize every record up front. Any single bad shape
472	      // (or value JSON cannot carry) rejects the whole group before the
473	      // serial chain is touched: seq/bytes/published/dedup/positions stay
474	      // exactly as they were.
475	      const prepared = [];
476	      try {
477	        for (const record of records) {
478	          if (record === null || typeof record !== 'object' || Array.isArray(record)) {
479	            throw new TypeError('publishBatch: record must be a JSON object');
480	          }
481	          const dedupKey = record.dedupKey;
482	          if (dedupKey !== undefined && typeof dedupKey !== 'string') {
483	            throw new TypeError('publishBatch: dedupKey must be a string');
484	          }
485	          assertJsonSafe(record);
486	          // Serialize exactly once per record: the byte count used for
487	          // stats and the bytes actually appended must be the same string.
488	          const recordJson = JSON.stringify(record);
489	          prepared.push({
490	            dedupKey,
491	            recordJson,
492	            size: Buffer.byteLength(recordJson, 'utf8'),
493	          });
494	        }
495	      } catch (err) {
496	        return Promise.reject(err);
497	      }
498	      if (prepared.length === 0) {
499	        return Promise.resolve([]);
500	      }
501	
502	      // Reserve the group's first-occurrence keys at call time, mirroring
503	      // publish()'s `pending`: a concurrent single or batch carrying the
504	      // same key shares this group's first acknowledgement. Keys already in
505	      // history or reserved by an earlier in-flight op are left alone.
506	      const reservations = new Map();
507	      for (const item of prepared) {
508	        const key = item.dedupKey;
509	        if (key === undefined) continue;
510	        if (dedup.has(key) || pending.has(key) || groupPending.has(key)) continue;
511	        if (reservations.has(key)) continue;
512	        let resolveResult;
513	        let rejectResult;
514	        const promise = new Promise((resolve, reject) => {
515	          resolveResult = resolve;
516	          rejectResult = reject;
517	        });
518	        // This promise is a coordination primitive: callers that race the
519	        // reservation attach their own branch (publish returns it). A group
520	        // with no such racer would otherwise leave the rejection unhandled
521	        // when the bus closes before the job runs. The noop branch only
522	        // handles the event for the process; racers still observe it.
523	        promise.catch(() => {});
524	        const reservation = { promise, resolve: resolveResult, reject: rejectResult };
525	        reservations.set(key, reservation);
526	        groupPending.set(key, reservation);
527	      }
528	
529	      return enqueue(() => {
530	        if (closed || broken) {
531	          throw new Error('bus is closed');
532	        }
533	
534	        // Resolve the whole plan against durable state inside the serial
535	        // job, so groups queued behind earlier publishes/batches observe
536	        // their committed dedup keys.
537	        const gid = randomUUID();
538	        let nextSeq = seq;
539	        const owned = new Map(); // key -> first acknowledgement within group
540	        const keyAcks = new Map(); // every dedup key's resolved acknowledgement
541	        const planned = prepared.map((item) => {
542	          const key = item.dedupKey;
543	          if (key !== undefined) {
544	            const hist = dedup.get(key);
545	            if (hist) {
546	              const reuse = { id: hist.id, seq: hist.seq };
547	              keyAcks.set(key, reuse);
548	              return { reuse };
549	            }
550	            const earlier = owned.get(key);
551	            if (earlier) {
552	              return { reuse: earlier };
553	            }
554	          }
555	          nextSeq += 1;
556	          const id = randomUUID();
557	          const ack = { id, seq: nextSeq };
558	          if (key !== undefined) {
559	            owned.set(key, ack);
560	            keyAcks.set(key, ack);
561	          }
562	          // Splice the already-serialized record into the line so the
563	          // persisted bytes are exactly what `size` counted.
564	          let line = `{"t":"m","seq":${nextSeq},"id":${JSON.stringify(id)},"bytes":${item.size}`;
565	          if (key !== undefined) line += `,"d":${JSON.stringify(key)}`;
566	          line += `,"record":${item.recordJson}}\n`;
567	          return { effective: { ack, line, size: item.size, key } };
568	        });
569	
570	        // One begin-bracket, the group's new messages, one commit-bracket.
571	        // Recovery applies the bracketed entries only when the commit is
572	        // present, so a crash leaves no trace of the group.
573	        const buffers = [Buffer.from(JSON.stringify({ t: 'b', id: gid }) + '\n', 'utf8')];
574	        for (const part of planned) {
575	          if (part.effective) {
576	            buffers.push(Buffer.from(part.effective.line, 'utf8'));
577	          }
578	        }
579	        buffers.push(Buffer.from(JSON.stringify({ t: 'bk', id: gid }) + '\n', 'utf8'));
580	
581	        try {
582	          // Coalesce in small chunks (bounds peak memory for huge groups)
583	          // and loop over partial writes. Single-buffer writeSync is used
584	          // rather than writev so the append behaves identically on Windows.
585	          // Everything here is synchronous inside this job, so no position
586	          // write can interleave. The begin/commit brackets keep the group
587	          // atomic across a crash even if a partial write occurs.
588	          const CHUNK = 256;
589	          for (let i = 0; i < buffers.length; i += CHUNK) {
590	            const chunk = Buffer.concat(buffers.slice(i, i + CHUNK));
591	            let off = 0;
592	            while (off < chunk.length) {
593	              const written = writeSync(fd, chunk, off, chunk.length - off);
594	              if (!Number.isInteger(written) || written <= 0) {
595	                throw new Error('publishBatch: write made no progress, group is not durable');
596	              }
597	              off += written;
598	            }
599	          }
600	          if (fsync) fsyncSync(fd);
601	        } catch (err) {
602	          // Nothing is applied in memory; the uncommitted bracket is
603	          // severed on reopen. Stop the bus so later writes cannot glue
604	          // themselves onto the partial group. Reservations are reclaimed
605	          // by the outer catch below.
606	          broken = true;
607	          throw err;
608	        }
609	
610	        // Durable first, state after.
611	        for (const part of planned) {
612	          if (!part.effective) continue;
613	          const { ack, size, key } = part.effective;
614	          seq = ack.seq;
615	          bytes += size;
616	          published += 1;
617	          if (key !== undefined) dedup.set(key, { id: ack.id, seq: ack.seq });
618	        }
619	
620	        const acks = planned.map((part) =>
621	          part.reuse ? { id: part.reuse.id, seq: part.reuse.seq } : { id: part.effective.ack.id, seq: part.effective.ack.seq },
622	        );
623	        for (const [key, reservation] of reservations) {
624	          groupPending.delete(key);
625	          reservation.resolve(keyAcks.get(key));
626	        }
627	        return acks;
628	      }).catch((err) => {
629	        // Covers write failure inside the job and rejection before the job
630	        // body (closed/broken bus): release any reservation still pointing
631	        // at this failed group.
632	        for (const [key, reservation] of reservations) {
633	          if (groupPending.get(key) === reservation) groupPending.delete(key);
634	          reservation.reject(err);
635	        }
636	        throw err;
637	      });
638	    },
639	
640	    replay(from = 0) {
641	      if (closed) {
642	        return Promise.reject(new Error('bus is closed'));
643	      }
644	      if (typeof from !== 'number' || !Number.isInteger(from) || from < 0) {
645	        return Promise.reject(new RangeError('replay: from must be a non-negative integer'));
646	      }
647	
648	      return enqueue(() => {
649	        if (closed || broken) {
650	          throw new Error('bus is closed');
651	        }
652	        // replay(from) is inclusive of from; messagesAfter takes an
653	        // exclusive lower bound.
654	        const out = messagesAfter(from - 1);
655	        const n = out.length;
656	        if (n > 0) {
657	          try {
658	            writeLine({ t: 's', n });
659	          } catch (err) {
660	            broken = true;
661	            throw err;
662	          }
663	          replayed += n;
664	        }
665	        return out;
666	      });
667	    },
668	
669	    register(name) {
670	      assertOpen();
671	      assertName(name);
672	      const current = positions.get(name);
673	      // Re-registering an existing name must not reset its position.
674	      if (current !== undefined) {
675	        return current;
676	      }
677	      persistPosition(name, 0);
678	      positions.set(name, 0);
679	      return 0;
680	    },
681	
682	    advance(name, to) {
683	      assertOpen();
684	      assertName(name);
685	      if (typeof to !== 'number' || !Number.isInteger(to) || to < 0) {
686	        throw new RangeError('advance: position must be a non-negative integer');
687	      }
688	      const current = positions.get(name);
689	      if (current !== undefined) {
690	        if (to < current) {
691	          throw new RangeError('advance: position cannot move backwards');
692	        }
693	        if (to === current) {
694	          return current;
695	        }
696	      }
