698	      persistPosition(name, to);
699	      positions.set(name, to);
700	      return to;
701	    },
702	
703	    read(name) {
704	      assertOpen();
705	      assertName(name);
706	      let pos = positions.get(name);
707	      if (pos === undefined) {
708	        pos = 0;
709	        persistPosition(name, pos);
710	        positions.set(name, pos);
