742	        const snapshot = {
743	          v: 1,
744	          gen,
745	          seq,
746	          bytes,
747	          published,
748	          replayed,
749	          horizon,
750	          positions: Object.fromEntries(positions),
751	          dedup: Array.from(dedup.entries()),
