881	        // Deletion is a prefix of the segment chain: sweep oldest first and
882	        // stop at the first segment that must stay. A segment stays while
883	        // any registered consumer's position has not passed its newest
884	        // message, or while that message is beyond the bound. A segment
885	        // without messages carries no retention weight and goes with the
886	        // prefix (its position/stat lines are checkpointed below).
887	        const doomed = [];
888	        let newHorizon = horizon;
889	        for (const seg of listSegments()) {
890	          const max = segmentMaxSeq(seg.path);
891	          if (max !== null) {
892	            if (max <= foldedSeq) continue; // pre-compaction leftover, not truncation's job
893	            if (max > before) break;
894	            let held = false;
895	            for (const pos of positions.values()) {
896	              if (pos < max) {
