907	        if (doomed.length === 0) {
908	          return;
909	        }
910	
911	        // Checkpoint every state the doomed segments carry BEFORE unlinking
912	        // them. The marker is the first line of the fresh active segment and
913	        // becomes the new recovery anchor, so a crash after it lands loses
914	        // nothing: recovery resets to the marker and reconciles leftovers.
915	        const marker = {
916	          t: 't',
917	          gen: snapshotGen,
918	          horizon: newHorizon,
919	          seq,
920	          bytes,
921	          published,
922	          replayed,
923	          positions: Object.fromEntries(positions),
924	          dedup: Array.from(dedup.entries()),
925	        };
