957	            }
958	          }
959	          // Best-effort durability for the unlinks; a crash here recovers to
960	          // the marker plus whichever segments remain — both consistent.
961	          try {
962	            const dirFd = openSync(dir, 'r');
963	            try {
964	              fsyncSync(dirFd);
965	            } finally {
966	              closeSync(dirFd);
967	            }
968	          } catch {
969	            // Unlink durability is best-effort; leftovers are harmless.
970	          }
971	        }
