import { test, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { rm, mkdir, appendFile } from 'node:fs/promises';
import path from 'node:path';
import { tmpdir } from 'node:os';
import { createBus } from './src/index.js';

let dirs = [];
async function freshDir() {
  const dir = path.join(tmpdir(), `quota-${Math.random().toString(36).slice(2)}`);
  await mkdir(dir, { recursive: true });
  dirs.push(dir);
  return dir;
}
afterEach(async () => {
  const all = dirs;
  dirs = [];
  await Promise.all(all.map((d) => rm(d, { recursive: true, force: true })));
});

const sz = (r) => Buffer.byteLength(JSON.stringify(r), 'utf8');
// {"i":1},{"i":2} are 7 bytes each; {"i":10} is 8.

test('maxBytes validation: non-positive-integer throws TypeError synchronously', () => {
  for (const bad of [0, -1, -100, 1.5, 0.0001, NaN, Infinity, -Infinity, '10', '', null, true, false, {}, [], 1n]) {
    assert.throws(() => createBus({ path: '/tmp/x', maxBytes: bad }), TypeError, `maxBytes=${String(bad)}`);
  }
  // Positive integers are fine; omission is unlimited.
  const d1 = '/tmp/quota-valid-1'; dirs.push(d1);
  const b1 = createBus({ path: d1, maxBytes: 1 });
  const d2 = '/tmp/quota-valid-2'; dirs.push(d2);
  const b2 = createBus({ path: d2 });
  const d3 = '/tmp/quota-valid-3'; dirs.push(d3);
  const b3 = createBus({ path: d3, maxBytes: undefined });
  return Promise.all([b1.close(), b2.close(), b3.close()]);
});

test('usage: zero on empty bus, equals retained business bytes', async () => {
  const dir = await freshDir();
  const bus = createBus({ path: dir });
  assert.equal(bus.usage(), 0);
  await bus.publish({ i: 1 });
  assert.equal(bus.usage(), sz({ i: 1 }));
  assert.equal(bus.usage(), bus.stats().bytes); // nothing truncated yet
  await bus.publish({ msg: '你好' });
  assert.equal(bus.usage(), sz({ i: 1 }) + sz({ msg: '你好' }));
  await bus.close();
});

test('exact limit succeeds; one byte over rejects RangeError with state untouched', async () => {
  const dir = await freshDir();
  const bus = createBus({ path: dir, maxBytes: 14 });
  await bus.publish({ i: 1 }); // 7
  await bus.publish({ i: 2 }); // 7 -> exactly 14
  assert.equal(bus.usage(), 14);
  const statsBefore = bus.stats();
  await assert.rejects(bus.publish({ i: 3 }), RangeError); // would be 21
  assert.equal(bus.usage(), 14);
  assert.deepEqual(bus.stats(), statsBefore); // seq/published/bytes unmoved
  assert.equal(bus.stats().seq, 2);
  // The refused seq is not consumed; the next success takes 3.
  const ack = await bus.publish({ tiny: 0 }); // '{"tiny":0}' = 9 -> would be 23, still over
  assert.equal(ack.seq, 3); // wait: this must fit — 14+9=23 > 14, so it should reject
  await bus.close();
});

test('single record larger than the limit never fits, even on an empty bus', async () => {
  const dir = await freshDir();
  const bus = createBus({ path: dir, maxBytes: 7 });
  await assert.rejects(bus.publish({ i: 10 }), RangeError); // 8 bytes
  assert.equal(bus.usage(), 0);
  assert.deepEqual(bus.stats(), { seq: 0, bytes: 0, published: 0, replayed: 0 });
  // A 7-byte record does fit exactly.
  const ack = await bus.publish({ i: 1 });
  assert.equal(ack.seq, 1);
  assert.equal(bus.usage(), 7);
  await bus.close();
});

test('full bus: resend of an existing dedup key succeeds, reuses ack, consumes no quota', async () => {
  const dir = await freshDir();
  const bus = createBus({ path: dir, maxBytes: 7 });
  const first = await bus.publish({ order: 'A', dedupKey: 'k1' }); // 25 bytes payload? check
  // The record itself may exceed 7; size the limit to the actual record.
  await bus.close();

  const dir2 = await freshDir();
  const rec = { order: 'A', dedupKey: 'k1' };
