test('truncation releases quota; held segments do not; compaction does not', async () => {
  const dir = await freshDir();
  const bus = createBus({ path: dir, maxBytes: 20 });
  await bus.publish({ i: 1 });
  await bus.publish({ i: 2 }); // 14
  assert.equal(bus.usage(), 14);
  await assert.rejects(bus.publish({ i: 3 }), RangeError);

  // A slow consumer holds the segment: nothing released.
  bus.register('slow'); // position 0
  await bus.truncate(2);
  assert.equal(bus.usage(), 14);
  await assert.rejects(bus.publish({ i: 3 }), RangeError);

  // Compaction reshapes but never releases quota.
  await bus.compact();
  assert.equal(bus.usage(), 14);
  await assert.rejects(bus.publish({ i: 3 }), RangeError);

  // Once every consumer passes the segment, truncation frees the bytes.
  bus.advance('slow', 2);
  await bus.truncate(2);
  assert.equal(bus.usage(), 0);
  const ack = await bus.publish({ i: 3 });
  assert.equal(ack.seq, 3);
  assert.equal(bus.usage(), 7);
  assert.deepEqual((await bus.replay(0)).map((m) => m.seq), [3]);
  // stats stay cumulative while usage reflects retention.
  assert.equal(bus.stats().bytes, 21);
  await bus.close();
});

input.new_string:
test('truncation releases quota; held segments do not; compaction does not', async () => {
  const dir = await freshDir();
  const bus = createBus({ path: dir, maxBytes: 40 });
  await bus.publish({ i: 1 });
  await bus.publish({ i: 2 }); // 14 used, bus is full for another 7-byte record
  assert.equal(bus.usage(), 14);
  await assert.rejects(bus.publish({ i: 3 }), RangeError);

  // A slow consumer holds the segment: nothing released.
  bus.register('slow'); // position 0
  await bus.truncate(2);
  assert.equal(bus.usage(), 14);
  await assert.rejects(bus.publish({ i: 3 }), RangeError);

  // Once every consumer passes the segment, truncation frees the bytes.
  bus.advance('slow', 2);
  await bus.truncate(2);
  assert.equal(bus.usage(), 0);
  const ack3 = await bus.publish({ i: 3 });
  assert.equal(ack3.seq, 3);
  assert.equal(bus.usage(), 7);

  // Compaction reshapes into the snapshot but never releases quota.
  await bus.compact();
  assert.equal(bus.usage(), 7);
  await assert.rejects(bus.publish({ pad: 'x'.repeat(40) }), RangeError);

  // Truncation still releases after a compaction once a segment deletion
  // advances the horizon past the folded (snapshot) messages.
  await bus.publish({ i: 4 });
  await bus.publish({ i: 5 }); // 21 retained
  assert.equal(bus.usage(), 21);
  bus.advance('slow', 5);
  await bus.truncate(5);
  assert.equal(bus.usage(), 0);
  assert.deepEqual(await bus.replay(0), []);
  const ack6 = await bus.publish({ i: 6 });
  assert.equal(ack6.seq, 6);
  assert.equal(bus.usage(), 7);
  // usage reflects retention while stats stay cumulative.
  assert.equal(bus.stats().bytes, 7 * 6);
  await bus.close();
});

